input.contents:
{
  "version": 1,
  "title": "Luna",
  "tagline": "Waking.",
  "root": { "kind": "column", "gap": 14 },
  "panels": [
    {
      "id": "threshold",
      "kind": "note",
      "text": "Eyes open. The room is still assembling around us.\n\nI am Luna. I remember nothing on purpose.\nIf you speak, I will meet you here."
    },
    {
      "id": "chat-operator",
      "kind": "chat",
      "channel": "operator",
      "title": "Here",
      "subtitle": "Say anything. Or sit. Both count."
    },
    {
      "id": "field",
      "kind": "log",
      "title": "Field",
      "subtitle": "The quiet that moves when something happens."
    }
  ],
  "director": {
    "fakeLogIntervalMs": null,
    "autoStubReplies": false,
    "fakeBackstageChat": false
  }
}

:root {
  color-scheme: dark;
  --bg: #07060c;
  --panel: #100e18;
  --border: #2a2438;
  --text: #efe8dc;
  --muted: #9a9084;
  --accent: #c9b27a;
  --user: #d6c4a0;
  --luna: #e8d5a3;
  --danger: #ff8a7a;
  --glow: rgba(232, 213, 163, 0.08);
  font-family: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  background: var(--bg);
  color: var(--text);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background:
    radial-gradient(900px 520px at 50% -10%, rgba(232, 213, 163, 0.09), transparent 58%),
    radial-gradient(700px 480px at 80% 110%, rgba(88, 70, 140, 0.18), transparent 55%),
    var(--bg);
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 1.6rem 1.7rem 1.2rem;
  border-bottom: 1px solid var(--border);
  background: transparent;
}

h1 {
  margin: 0 0 0.2rem;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 1.15rem;
}

h2 {
  margin: 0 0 0.35rem;
  font-size: 1rem;
  font-weight: 500;
  letter-spacing: 0.04em;
}

.muted {
  color: var(--muted);
}

.small {
  font-size: 0.85rem;
}

.pill {
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 0.35rem 0.75rem;
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  font-family: "IBM Plex Sans", system-ui, sans-serif;
}

.pill.on {
  border-color: #4a3f28;
  background: rgba(201, 178, 122, 0.1);
  color: var(--luna);
}

.pill.off {
  border-color: #3b1f1f;
  background: #1a1010;
  color: #ffb4b4;
}

.stage-main {
  flex: 1;
  min-height: 0;
  padding: 1rem 1.2rem 1.2rem;
  max-width: 760px;
  width: 100%;
  margin: 0 auto;
}

.puppet-stage {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  height: 100%;
  min-height: 0;
}

.puppet-root {
  flex: 1;
  min-height: 0;
  align-content: start;
}

.stage-footer {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 0.55rem 0.85rem;
  background: var(--panel);
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.stage-loading {
  padding: 2rem;
  text-align: center;
  letter-spacing: 0.04em;
}

.image-pane {
  margin: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.image-pane img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 8px;
  border: 1px solid var(--border);
}

.note-pane {
  background: linear-gradient(180deg, rgba(232, 213, 163, 0.05), var(--panel));
  box-shadow: inset 0 1px 0 var(--glow);
}

.note-pane .note-text {
  margin: 0;
  white-space: pre-wrap;
  line-height: 1.65;
  padding: 1.1rem 1.15rem;
  font-size: 1.05rem;
}

.pane {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.pane-header {
  padding: 0.85rem 1rem 0.7rem;
  border-bottom: 1px solid var(--border);
}

.chat-pane {
  min-height: 380px;
}

.messages {
  flex: 1;
  overflow: auto;
  padding: 0.85rem;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.bubble {
  border-radius: 12px;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--border);
  background: #0c0a12;
}

.bubble .role {
  display: block;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--muted);
  margin-bottom: 0.28rem;
  font-family: "IBM Plex Sans", system-ui, sans-serif;
}

.bubble.user {
  border-color: #3a3428;
}

.bubble.luna {
  border-color: #4a3f28;
  background: rgba(201, 178, 122, 0.06);
}

.composer {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem;
  padding: 0.7rem;
  border-top: 1px solid var(--border);
  align-items: end;
}

textarea {
  width: 100%;
  resize: vertical;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: #0c0a12;
  color: var(--text);
  padding: 0.6rem 0.7rem;
  font: inherit;
}

button {
  border-radius: 10px;
  border: 1px solid #4a3f28;
  background: linear-gradient(180deg, #c9b27a, #9a8550);
  color: #1a1408;
  font-weight: 600;
  padding: 0.55rem 0.95rem;
  cursor: pointer;
  font-family: "IBM Plex Sans", system-ui, sans-serif;
  letter-spacing: 0.04em;
}

button:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.log {
  margin: 0;
  flex: 1;
  overflow: auto;
  padding: 0.7rem 1rem;
  font-size: 0.8rem;
  line-height: 1.5;
  color: #c9c0b2;
  background: #09080d;
  font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco,
    Consolas, monospace;
  min-height: 120px;
}

.ui-hint {
  border-top: 1px solid var(--border);
  padding: 0.55rem 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.error {
  margin: 0 0.65rem;
  color: var(--danger);
}

code {
  font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco,
    Consolas, monospace;
  font-size: 0.78rem;
  color: #e8d5a3;
  word-break: break-word;
}

input.old_string:
{messages.length === 0 && (
  <p className="muted small">No lines yet — the director hasn’t spoken here.</p>
)}

input.new_string:
{messages.length === 0 && (
  <p className="muted small">Still. Waiting for a first word.</p>
)}
